<script setup>
import{onMounted,ref}from'vue';import{apiErrorMessage,showToast}from'./uiFeedback';const api=import.meta.env.VITE_API_BASE||'/api',token=localStorage.getItem('support_token')||'';const notices=ref([]),count=ref(0),sending=ref(false),form=ref({title:'系统维护升级通知',noticeType:'maintenance',startTime:'',endTime:'',impactScope:'工单系统、问题库、远程运维',content:'系统计划进行升级维护，维护期间部分功能可能暂时无法访问，请提前保存正在处理的内容。'});function h(){return{Authorization:`Bearer ${token}`,'Content-Type':'application/json'}}async function req(u,o={}){o.headers={...h(),...(o.headers||{})};let r=await fetch(u,o);if(!r.ok)throw new Error(await apiErrorMessage(r));return r.json()}function t(v){return v?String(v).replace('T',' ').slice(0,19):'-'}async function load(){try{[notices.value,{recipientCount:count.value}]=await Promise.all([req(`${api}/admin/maintenance-notices`),req(`${api}/admin/maintenance-notices/preview`)])}catch(e){showToast(e.message)}}async function createAndSend(){if(!form.value.title.trim()||!form.value.content.trim())return showToast('请填写标题和维护说明');if(!confirm(`确认发布维护通知？\n将向 ${count.value} 个有效邮箱发送邮件。\n\n发送后不能撤回。`))return;sending.value=true;try{let n=await req(`${api}/admin/maintenance-notices`,{method:'POST',body:JSON.stringify(form.value)});await req(`${api}/admin/maintenance-notices/${n.id}/send`,{method:'POST',body:'{}'});showToast('维护通知已进入发送队列','success');await load()}catch(e){showToast(e.message)}finally{sending.value=false}}async function retry(n){if(!confirm(`仅重试该通知的 ${n.failed_count||0} 个失败收件人？`))return;try{await req(`${api}/admin/maintenance-notices/${n.id}/send`,{method:'POST',body:JSON.stringify({retryFailed:true})});showToast('失败邮件已进入重试队列','success');await load()}catch(e){showToast(e.message)}}onMounted(load)
</script>
<template><main class="page"><section class="admin-header"><div><span class="badge">SYSTEM MANAGEMENT</span><h1>系统维护通知</h1><p>管理员发布升级/维护邮件。发送任务异步执行，并记录成功、失败与重试状态。</p></div><a class="back-link" href="/admin">返回管理后台</a></section><section class="grid"><div class="panel editor"><div class="panel-title"><div><h2>发布维护通知</h2><p class="muted">当前有效收件邮箱：<b>{{count}}</b> 个。发送前会再次确认。</p></div></div><label>通知类型<select v-model="form.noticeType"><option value="maintenance">维护 / 升级通知</option><option value="completed">维护完成通知</option></select></label><label>邮件标题<input v-model="form.title" maxlength="200"></label><div class="two"><label>开始时间<input v-model="form.startTime" type="datetime-local"></label><label>预计结束<input v-model="form.endTime" type="datetime-local"></label></div><label>影响范围<input v-model="form.impactScope" maxlength="500"></label><label>通知说明<textarea v-model="form.content" rows="8" maxlength="10000"></textarea></label><div class="preview"><strong>邮件预览</strong><p>各位用户，您好：</p><p>{{form.content}}</p><p v-if="form.startTime">维护开始：{{form.startTime.replace('T',' ')}}</p><p v-if="form.endTime">预计结束：{{form.endTime.replace('T',' ')}}</p><p v-if="form.impactScope">影响范围：{{form.impactScope}}</p><p>MYROBOOT 技术支持平台</p></div><button class="primary" :disabled="sending||!count" @click="createAndSend">{{sending?'正在创建任务…':`确认并通知 ${count} 名用户`}}</button></div><div class="panel"><h2>发送记录</h2><div class="history"><article v-for="n in notices" :key="n.id"><div><strong>{{n.title}}</strong><small>{{t(n.create_time)}} · {{n.creator_name||'管理员'}}</small></div><span class="status">{{n.status}}</span><div class="numbers"><span>目标 {{n.total_count}}</span><span>成功 {{n.sent_count}}</span><span>失败 {{n.failed_count}}</span></div><button v-if="n.status==='failed'||n.status==='partial_failed'" class="secondary small-btn" @click="retry(n)">只重试失败邮件</button></article><div v-if="!notices.length" class="muted">暂无维护通知记录</div></div></div></section></main></template>
<style scoped>.grid{display:grid;grid-template-columns:1.05fr .95fr;gap:20px}.editor{display:grid;gap:14px}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.preview{background:#f7f9fc;border:1px solid #e1e7ef;border-radius:12px;padding:15px;white-space:pre-wrap}.preview p{margin:8px 0}.history{display:grid;gap:10px}.history article{display:grid;grid-template-columns:1fr auto;gap:8px;border:1px solid #e3e9f1;border-radius:12px;padding:13px}.history article>div:first-child{display:grid}.history small{color:#7d8da4}.numbers{grid-column:1/-1;display:flex;gap:16px}.status{font-family:monospace}@media(max-width:850px){.grid,.two{grid-template-columns:1fr}}</style>
